WITH park_point AS (
  SELECT ST_SetSRID(ST_MakePoint(-82.203894, 35.80555), 4326)::geography AS geom
),
ruggedness_raster AS (
  SELECT 
    ST_MapAlgebra(
      a.rast,
      1,
      'ruggedness(double[][] sample, int width, int height, double pixelSize) returns double[][]',
      'ruggedness(double[][] sample, int width, int height, double pixelSize) {
        double[][] result = new double[width][height];
        for (int i = 0; i < width; i++) {
          for (int j = 0; j < height; j++) {
            if (i == 0 || i == width - 1 || j == 0 || j == height - 1) {
              result[i][j] = 0;
              continue;
            }
            double maxElev = -Double.MAX_VALUE;
            double minElev = Double.MAX_VALUE;
            for (int di = -1; di <= 1; di++) {
              for (int dj = -1; dj <= 1; dj++) {
                if (di == 0 && dj == 0) continue;
                double elev = sample[i + di][j + dj];
                maxElev = Math.max(maxElev, elev);
                minElev = Math.min(minElev, elev);
              }
            }
            result[i][j] = maxElev - minElev;
          }
        }
        return result;
      }',
      '32BF',
      'last'
    ) AS ruggedness_rast
  FROM public.dem_us a, park_point p
  WHERE ST_Intersects(a.rast::geometry, p.geom)
),
clipped_ruggedness AS (
  SELECT 
    ST_Clip(ruggedness_rast, p.geom::geometry, true) AS clipped_rast
  FROM ruggedness_raster, park_point p
)
SELECT 
  ST_Stats(clipped_rast, 1, true).mean AS ruggedness_index
FROM clipped_ruggedness;
